package local.lito381.server;
import java.io.*;import java.util.*;
/** Corpse admission is distinct from live combat capture; use existing context/receipt/publication owners. */
final class NativeCompanionResurrection {
 static final class Corpse {
  final NativeCompanionCallbacks.Stamp stamp;final Object bag,pose;final NativeCompanionPlacement.State placement;final NativeCompanionPlacement.Scene scene;
  final int x,y,hp;final boolean active;Object revived;
  Corpse(NativePlayerCommit.Binding binding,ClientSession owner,BattleCompanion pet,NativeAreaMaterialAction.Context c){var s=pet.snapshot();stamp=NativeCompanionCallbacks.capture(binding,pet);bag=CombatAccess.field(pet,"carriedItems");placement=NativeCompanionPlacement.state(pet);scene=placement==null?new NativeCompanionPlacement.Scene(c.hub,c.map,c.instance):placement.scene;pose=placement==null?null:placement.pose;x=s.x();y=s.y();hp=s.hp();active=s.active();}
 }
 static final class NpcCorpse {final Object life;final int x,y,hp;final boolean active,present;Object revived;NpcCorpse(Object life,ClassicWorldMonsterPopulation.Snapshot s){this.life=life;x=s.x();y=s.y();hp=s.currentHp();active=s.alive();present=s.present();}}
 static NativeAreaMaterialAction.Context context(ClientSession pc){var c=NativeAreaMaterialAction.current.get();return NativeCompanionNegative.owns(c,pc)&&c.nativeCorpseTargetScope?c:null;}
 static ClientSession capture(NativeAreaMaterialAction.Context c,long id){
  for(var pc:c.players)if(pc.playerObjectId()==id&&c.player(pc))return pc;
  synchronized(c.hub){for(var owner:c.players)for(var snapshot:NativeCompanionPlacement.inScene(owner,c.map,c.instance))if(snapshot.objectId()==id){var pet=(BattleCompanion)CombatAccess.call(owner,"ownedCompanion","(J)Llocal/lito381/server/BattleCompanion;",id);var binding=c.bindings.get(owner);if(pet!=null&&binding!=null)synchronized(pet){c.npcs.put(id,new NativeAreaMaterialAction.Npc(3,id,owner,pet,new Corpse(binding,owner,pet,c)));return owner;}}
   var snapshot=c.hub.classicWorldMonster(c.map,c.instance,id);var actor=c.population==null?null:NativeCancellationNpcMaterialAction.actor(c.population,id);if(snapshot!=null&&actor!=null)c.npcs.put(id,new NativeAreaMaterialAction.Npc(0,id,c.population,actor,new NpcCorpse(NativeCancellationNpcMaterialAction.epoch(actor,true),snapshot)));
  }return c.pc;
 }
 static void scope(ClientSession pc,byte[] packet,NativeSelfCastAction.Task body)throws IOException{
  if(!NativeCompanionPlacement.world(pc)){body.run();return;}long id=Protocol.objectSpellRequest(packet).targetObjectId();var inherited=context(pc);if(inherited!=null&&(long)CombatAccess.field(inherited,NativeCompanionNegative.ID)==id){body.run();return;}
  var c=new NativeAreaMaterialAction.Context(pc);c.nativeCorpseTargetScope=true;var owner=capture(c,id);var receipt=owner==pc?null:NativePlayerVitalCompletions.reserve(owner);if(owner!=pc&&receipt==null)return;
  CombatAccess.set(c,NativeCompanionNegative.STAGE,1);CombatAccess.set(c,NativeCompanionNegative.ID,id);CombatAccess.set(c,NativeCompanionNegative.RECEIPT,receipt);var prior=NativeAreaMaterialAction.current.get();NativeAreaMaterialAction.current.set(c);
  try{body.run();}finally{if(prior==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(prior);if(receipt!=null&&!receipt.released.get())receipt.close();}
 }
 static void dispatch(ClientSession pc,byte[] packet,NativeSelfCastAction.Task original)throws IOException{int skill=Protocol.spellSelector(packet).skillId();if((skill==61||skill==75)&&NativeCompanionPlacement.world(pc)&&!pc.selectedCharacterName().isBlank())scope(pc,packet,()->NativeResurrectionMaterialAction.nativeSceneOriginalDispatch(pc,packet,original));else NativeResurrectionMaterialAction.nativeSceneOriginalDispatch(pc,packet,original);}
 static void world(ClientSession pc,byte[] packet,BattleSpellCatalog.ResurrectionSpell spell)throws IOException{scope(pc,packet,()->NativeResurrectionMaterialAction.nativeSceneOriginalWorld(pc,packet,spell));}
 static boolean valid(NativeAreaMaterialAction.Context c,NativeAreaMaterialAction.Npc n,boolean after){
  if(n.epoch() instanceof NpcCorpse proof){synchronized(c.hub){var s=c.hub.classicWorldMonster(c.map,c.instance,n.id());return c.scene()&&!(boolean)CombatAccess.field(c.hub,"nativeStaticMotionClosed")&&NativeCancellationNpcMaterialAction.population(c.hub,c.map,c.instance)==n.owner()&&NativeCancellationNpcMaterialAction.actor(c.population,n.id())==n.actor()&&s!=null&&s.x()==proof.x&&s.y()==proof.y&&(after?proof.revived!=null&&s.alive()&&s.present()&&NativeCancellationNpcMaterialAction.epoch(n.actor(),false)==proof.revived:s.alive()==proof.active&&s.present()==proof.present&&s.currentHp()==proof.hp&&NativeCancellationNpcMaterialAction.epoch(n.actor(),false)==proof.life);}}
  if(!(n.epoch() instanceof Corpse proof))return true;var owner=(ClientSession)n.owner();var pet=(BattleCompanion)n.actor();synchronized(c.hub){synchronized(pet){var s=pet.snapshot();var placement=NativeCompanionPlacement.state(pet);return c.scene()&&!(boolean)CombatAccess.field(c.hub,"nativeStaticMotionClosed")&&proof.stamp.master.matches(owner)&&!(boolean)CombatAccess.field(owner,"sourceItemDisconnected")&&CombatAccess.call(owner,"ownedCompanion","(J)Llocal/lito381/server/BattleCompanion;",n.id())==pet&&s.objectId()==n.id()&&CombatAccess.field(pet,"carriedItems")==proof.bag&&s.x()==proof.x&&s.y()==proof.y&&placement==proof.placement&&proof.scene.at(c.map,c.instance)&&proof.scene.alive(c.hub)&&(placement==null?NativeCompanionPlacement.world(owner)&&NativeCompanionPlacement.map(owner)==c.map&&NativeCompanionPlacement.instance(owner)==c.instance:placement.role(owner)&&placement.scene==proof.scene&&placement.pose==proof.pose)&&(after?proof.revived!=null&&s.active()&&s.hp()>0&&NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),false)==proof.revived:s.active()==proof.active&&s.hp()==proof.hp&&NativeCompanionCallbacks.capture(proof.stamp.master,pet).life==proof.stamp.life);}}
 }
 static List<BattleCompanion.Snapshot> snapshots(ClientSession owner,ClientSession pc){var c=context(pc);var result=NativeCompanionPlacement.inScene(owner,NativeCompanionPlacement.map(pc),NativeCompanionPlacement.instance(pc));if(c==null)return result;long id=(long)CombatAccess.field(c,NativeCompanionNegative.ID);return result.stream().filter(s->{if(s.objectId()!=id)return true;var n=c.npcs.get(id);return n!=null&&n.kind()==3&&n.owner()==owner&&n.epoch() instanceof Corpse&&valid(c,n,false);}).toList();}
 static boolean admit(ClientSession pc,ClientSession player,int skill,int action,int reuse){var c=context(pc);if(c!=null){long id=(long)CombatAccess.field(c,NativeCompanionNegative.ID);if(!c.scene()||player!=null&&(!c.player(player)||player.playerObjectId()!=id))return false;var n=c.npcs.get(id);if(n!=null&&(n.epoch() instanceof Corpse||n.epoch() instanceof NpcCorpse)&&!valid(c,n,false))return false;}return NativeResurrectionMaterialAction.nativeSceneOriginalAdmit(pc,player,skill,action,reuse);}
 static boolean resurrect(BattleCompanion pet,int hp){var c=NativeAreaMaterialAction.current.get();var n=c==null?null:c.npcs.get(pet.snapshot().objectId());if(c!=null&&n!=null&&n.actor()==pet&&n.epoch() instanceof Corpse proof){synchronized(c.hub){synchronized(pet){if(!valid(c,n,false))return false;boolean result=pet.resurrect(hp);if(result)proof.revived=NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),false);return result;}}}return pet.resurrect(hp);}
 static ClassicWorldMonsterPopulation.Resurrection resurrectNpc(GameHub hub,int map,int instance,long id,int hp){var c=NativeAreaMaterialAction.current.get();var n=c==null?null:c.npcs.get(id);if(c!=null&&n!=null&&n.epoch() instanceof NpcCorpse proof){synchronized(hub){if(!valid(c,n,false))return null;var result=hub.resurrectClassicWorldMonster(map,instance,id,hp);if(result!=null)proof.revived=NativeCancellationNpcMaterialAction.epoch(n.actor(),false);return result;}}return hub.resurrectClassicWorldMonster(map,instance,id,hp);}
 static void send(ClientSession receiver,byte[] packet,String note)throws IOException{
  var c=NativeAreaMaterialAction.current.get();int opcode=packet.length==0?-1:packet[0]&255;long id=packet.length<5?-1:Integer.toUnsignedLong((packet[1]&255)|(packet[2]&255)<<8|(packet[3]&255)<<16|(packet[4]&255)<<24);var n=c==null?null:c.npcs.get(id);
  if(n==null||!(n.epoch() instanceof Corpse||n.epoch() instanceof NpcCorpse)||!Set.of(Protocol.S_EFFECT,Protocol.S_RESURRECT,Protocol.S_HIT_RATIO).contains(opcode)){receiver.nativeCorpseSend(packet,note);return;}
  byte[] frozen=packet.clone();var binding=c.bindings.get(receiver);if(binding==null)return;
  NativeLightAction.deferWeaponTargetOutput(()->{Runnable[] completion={null};NativeSourcePlayerActionLock.run(receiver,()->{if(binding.matches(receiver))completion[0]=NativeRolePublication.completion(receiver,()->{if(binding.matches(receiver)&&c.player(receiver)&&valid(c,n,true))try{receiver.nativeSelfOriginalSend(frozen,note);}catch(IOException e){throw new java.io.UncheckedIOException(e);}});});if(completion[0]!=null)completion[0].run();});
 }
 private NativeCompanionResurrection(){}
}
